//! Generated-crate snapshot inspection and ordinary Cargo-check preparation.

use std::{path::Path, process::Command};

use musubi_core::RuntimeSource;

use crate::{generated_release::ReleaseManifest, generated_tree::TreeSnapshot};

const MAX_IDENTITY_BYTES: usize = 256;

/// Validated generated-crate layout summary.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct GeneratedCrateReport {
    /// Number of owned source, asset, metadata and marker files.
    pub files: usize,
    /// Aggregate generated bytes.
    pub bytes: usize,
    /// Generated/runtime ABI contract version.
    pub generated_abi_version: u32,
    /// Exact manifest schema bound to the generated Rust root.
    pub manifest_schema: String,
    /// Exact manifest SHA-256 bound to both JSON and generated Rust.
    pub manifest_sha256: musubi_core::Sha256Digest,
    /// Explicit runtime source; paths are mutable and relative to the SDK.
    pub runtime: RuntimeSource,
    /// Recorded generator build information, independent of runtime source.
    pub generator: musubi_core::GeneratorInfo,
    /// Number of contract entries in the release manifest.
    pub contracts: usize,
    /// Number of closed typed-data authority entries in the release manifest.
    pub typed_data: usize,
}

/// Generated layout or compile-command preparation error.
#[derive(Clone, Copy, Debug, Eq, PartialEq, thiserror::Error)]
pub enum GeneratedCrateError {
    /// Root, marker, required files, or a nested filesystem entry is unsafe or malformed.
    #[error("generated crate layout is invalid or unsafe")]
    InvalidLayout,
    /// Generated file/byte budgets or retained ABI structural budgets exceed v1 limits.
    #[error("generated crate exceeds v1 output limits")]
    LimitExceeded,
}

/// A Cargo command backed by a private immutable-source snapshot.
///
/// Keep this value alive until any spawned Cargo child has exited. Dropping it removes the
/// private source and lockfile; reusable Cargo caches remain.
#[derive(Debug)]
pub struct GeneratedCargoCheck {
    prepared: musubi_codegen::PreparedCargoCheck,
}

impl GeneratedCargoCheck {
    /// Returns the prepared command for caller-owned timeout, output, and process handling.
    pub fn command_mut(&mut self) -> &mut Command {
        self.prepared.command_mut()
    }
}

/// Inspects marker ownership, required files, links, limits, and release identity.
///
/// Every file is opened relative to one retained root handle, bounded, and retained in memory
/// before release metadata is parsed. The inspected path is never reopened.
///
/// # Errors
///
/// Returns [`GeneratedCrateError`] for malformed layout, links, special entries, unknown release
/// schema, or v1-limit violations.
pub fn inspect_generated_crate(root: &Path) -> Result<GeneratedCrateReport, GeneratedCrateError> {
    inspect_snapshot(&TreeSnapshot::read(root)?)
}

/// Prepares an ordinary Cargo check using validated private source and lockfile copies.
///
/// Paths are resolved from `conceptual_sdk_root`, which must describe the SDK's original location,
/// even when `crate_root` is a relocated inspection copy. Trusted Cargo configuration is discovered
/// from `configuration_root`. Preparation uses bounded Cargo lockfile/metadata commands. The caller
/// owns bounded execution of the returned check and must retain its guard until children finish.
///
/// # Errors
///
/// Rejects malformed/unsafe source, failed preparation, invalid runtime paths, and cache/SDK overlap.
pub fn cargo_check_command(
    crate_root: &Path,
    conceptual_sdk_root: &Path,
    configuration_root: &Path,
) -> Result<GeneratedCargoCheck, GeneratedCrateError> {
    let snapshot = TreeSnapshot::read(crate_root)?;
    inspect_snapshot(&snapshot)?;
    let tree = musubi_codegen::GeneratedTree::from_files(
        snapshot
            .files
            .into_iter()
            .map(|(path, contents)| musubi_codegen::GeneratedFile { path, contents }),
    )
    .map_err(invalid)?;
    let prepared =
        musubi_codegen::prepare_cargo_check(&tree, conceptual_sdk_root, configuration_root)
            .map_err(invalid)?;
    Ok(GeneratedCargoCheck { prepared })
}

fn inspect_snapshot(snapshot: &TreeSnapshot) -> Result<GeneratedCrateReport, GeneratedCrateError> {
    snapshot.file("Cargo.toml")?;
    snapshot.file("src/lib.rs")?;
    let release_bytes = snapshot.file("musubi-release.json")?;
    let release: ReleaseManifest = serde_json::from_value(
        crate::closed_json::parse(release_bytes)
            .map_err(|()| GeneratedCrateError::InvalidLayout)?,
    )
    .map_err(invalid)?;
    let release = release.validate()?;
    if !valid_package_identity(&release.package.name, &release.package.version)
        || release.generator.validate().is_err()
        || release.generated_abi_version != musubi_core::GENERATED_ABI_VERSION
        || release.runtime.validate().is_err()
    {
        return Err(GeneratedCrateError::InvalidLayout);
    }
    crate::generated_cargo::validate(
        snapshot,
        &release.package.name,
        &release.package.version,
        &release.runtime,
    )?;
    crate::generated_inventory::validate(snapshot, &release)?;
    Ok(GeneratedCrateReport {
        files: snapshot.files.len(),
        bytes: snapshot.bytes,
        generated_abi_version: release.generated_abi_version,
        manifest_schema: release.manifest_schema,
        manifest_sha256: release.manifest_sha256,
        runtime: release.runtime,
        generator: release.generator,
        contracts: release.contracts.len(),
        typed_data: release.typed_data.len(),
    })
}

fn valid_package_identity(name: &str, version: &str) -> bool {
    let mut bytes = name.bytes();
    name.len() <= MAX_IDENTITY_BYTES
        && bytes
            .next()
            .is_some_and(|byte| byte == b'_' || byte.is_ascii_alphabetic())
        && bytes.all(|byte| byte == b'_' || byte == b'-' || byte.is_ascii_alphanumeric())
        && valid_version(version)
}

fn valid_version(value: &str) -> bool {
    value.len() <= MAX_IDENTITY_BYTES && semver::Version::parse(value).is_ok()
}

fn invalid<T>(_: T) -> GeneratedCrateError {
    GeneratedCrateError::InvalidLayout
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;

    fn write_released_fixture(root: &Path) {
        fs::write(root.join("Cargo.toml"), released_manifest()).unwrap();
        let mut release = serde_json::from_slice(
            br#"{
              "schema_version":"musubi/release-v4",
              "typed_data": [],
              "manifest_schema": "musubi/config-v4",
              "manifest_sha256": "0x7777777777777777777777777777777777777777777777777777777777777777",
              "package":{"name":"fixture","version":"0.1.0"},
              "generator": {"schema_version": "musubi/generator-info-v1", "version": "0.1.0", "revision": "unknown", "git_commit": null, "dirty": null, "build": {"rustc": "unknown", "host": "test-host", "target": "test-target", "profile": "test"}},
              "generated_abi_version": 2,
              "runtime":{
                "source":"git",
                "url":"ssh://git@github.com/craftguild/musubi.rs.git",
                "revision":"87553a40b014754de7991878c8e994490bad5939"
              },
              "contracts":[{
                "id":"vault",
                "rust_module": "vault",
                "kind": "deployable",
                "canonical_abi_sha256":"3333333333333333333333333333333333333333333333333333333333333333",
                "raw_abi_sha256":"1111111111111111111111111111111111111111111111111111111111111111",
                "creation_template_keccak256":"2222222222222222222222222222222222222222222222222222222222222222",
                "runtime_template_keccak256":null,
                "external_artifact_coherence":"unverified"
              }]
            }"#,
        )
        .unwrap();
        crate::generated_test_fixture::materialize(root, &mut release);
    }

    #[test]
    fn cargo_boundary_rejects_manifest_escape_and_implicit_targets() {
        for mutation in [
            "build = 'build.rs'\n",
            "autobins = false\n",
            "\n[workspace]\nmembers = ['/tmp/outside']\n",
            "\n[lib]\npath = '/tmp/outside.rs'\n",
        ] {
            let root = crate::generated_test_fixture::tempdir();
            write_released_fixture(root.path());
            let manifest = if mutation.starts_with('\n') {
                released_manifest()
                    .strip_suffix(b"\n")
                    .unwrap()
                    .iter()
                    .copied()
                    .chain(mutation.bytes())
                    .collect::<Vec<_>>()
            } else {
                let mut manifest = b"[package]\n".to_vec();
                manifest.extend_from_slice(mutation.as_bytes());
                manifest.extend_from_slice(&released_manifest()["[package]\n".len()..]);
                manifest
            };
            fs::write(root.path().join("Cargo.toml"), manifest).unwrap();
            crate::generated_test_fixture::reseal(root.path());
            assert!(inspect_generated_crate(root.path()).is_err());
        }

        let root = crate::generated_test_fixture::tempdir();
        write_released_fixture(root.path());
        let manifest = String::from_utf8(released_manifest().to_vec())
            .unwrap()
            .replace(
                "git='ssh://git@github.com/craftguild/musubi.rs.git'",
                "path='/tmp/outside'",
            );
        fs::write(root.path().join("Cargo.toml"), manifest).unwrap();
        crate::generated_test_fixture::reseal(root.path());
        assert!(inspect_generated_crate(root.path()).is_err());

        for path in ["build.rs", ".cargo/config.toml", "src/main.rs"] {
            let root = crate::generated_test_fixture::tempdir();
            write_released_fixture(root.path());
            let path = root.path().join(path);
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            fs::write(path, b"outside = true\n").unwrap();
            crate::generated_test_fixture::reseal(root.path());
            assert!(inspect_generated_crate(root.path()).is_err());
        }
    }

    fn released_manifest() -> &'static [u8] {
        b"[package]\nname='fixture'\nversion='0.1.0'\nedition='2024'\n\
          rust-version='1.95'\npublish=false\n\n[workspace]\n\n[dependencies]\n\
          musubi-core={git='ssh://git@github.com/craftguild/musubi.rs.git',rev='87553a40b014754de7991878c8e994490bad5939',package='musubi-core'}\n\
          musubi-runtime={git='ssh://git@github.com/craftguild/musubi.rs.git',rev='87553a40b014754de7991878c8e994490bad5939',package='musubi-runtime'}\n"
    }
}
